<?php use App\Services\Catalog; [$label,,$fields]=Catalog::TYPES[$table]; ?>
<?php if($table!=='fee_types'): ?><div class="tabs"><?php foreach(Catalog::TYPES as $key=>[$name]): if($key==='fee_types') continue; ?><a class="<?= $key===$table?'active':'' ?>" href="<?= e(url('academics',['table'=>$key])) ?>"><?= e($name) ?></a><?php endforeach ?></div><?php endif ?>
<div class="split"><section class="panel"><h2><?= e($label) ?></h2><p class="muted">School-owned configuration. Historical records retain their references.</p><div class="table-wrap"><table><thead><tr><th>Name</th><?php foreach($fields as $key=>$type): if($key==='name') continue; ?><th><?= e(ucwords(str_replace('_',' ',$key))) ?></th><?php endforeach ?></tr></thead><tbody><?php if(!$rows) emptyRow(count($fields)); foreach($rows as $r): ?><tr><td><a href="<?= e(url($table==='fee_types'?'fee-types':'academics',['table'=>$table,'edit'=>$r['id']])) ?>"><strong><?= e($r['name']) ?></strong></a></td><?php foreach($fields as $key=>$type): if($key==='name') continue; $value=$r[$key]; if(isset(Catalog::TYPES[$type])) { $opts=array_column(App\Services\Queries::options($type),'name','id'); $value=$opts[$value]??$value; } ?><td><?= e($type==='boolean'?($value?'Yes':'No'):$value) ?></td><?php endforeach ?></tr><?php endforeach ?></tbody></table></div></section><section class="panel"><h2><?= !empty($editing)?'Edit name':'Add '.e(strtolower($label)) ?></h2><?php if(!empty($editing)): ?><p class="muted">Names can be corrected. Dates, relationships and boarding rules are retained to protect historical records.</p><?php endif ?><?php startForm('catalog.save',['table'=>$table]+(!empty($editing)?['id'=>$editing['id']]:[]),'stack'); foreach($fields as $key=>$type) { $name=ucwords(str_replace(['_id','_'],['',' '],$key)); if(!empty($editing) && $key!=='name') { echo '<input type="hidden" name="'.e($key).'" value="'.e($editing[$key]).'">'; continue; } if($type==='boolean') selectField($key,$name,[['id'=>0,'name'=>'No — non-residential'],['id'=>1,'name'=>'Yes — boarding']],0); elseif(isset(Catalog::TYPES[$type])) selectField($key,$name,$type); else field($key,$name,$type,$editing[$key]??''); } endForm(!empty($editing)?'Save name':'Add configuration'); ?></section></div>
